// Package testmodel holds the entities of velox's own tests. They are
// generated by velox-gen from the DSL schema in the schema directory:
//
//	go build -o bin/velox-gen ./cmd/velox-gen && bin/velox-gen -out internal/testmodel -package testmodel ./internal/testmodel/schema
//
// Invoice and Ticket's Policy and Hooks are declared in the schema package,
// by column name, and the generated code binds them. The schema reads the
// organization and the user from package actor; Org, WithUser and
// UserFromContext (context.go) forward to it, and they and the aliases
// below are written by hand.
package testmodel

import "github.com/syssam/velox/internal/testmodel/kind"

// Status is a named string type: its handle is a StringCol.
type Status = kind.Status

// Cents is a named integer type: its handle is a NumberCol.
type Cents = kind.Cents

// Score is a named integer type: its handle is a NumberCol.
type Score = kind.Score

// Moment is a time type defined on time.Time: a time default converts to it.
type Moment = kind.Moment

// Dec is a decimal type of its own in a numeric column: its handle is a
// NumberCol.
type Dec = kind.Dec
